bool is_shared_builtin_user_table(const uint64_t tenant_id, const ObString &table_name)
{
  bool bret = false;
  if ((is_sys_tenant(tenant_id) || is_meta_tenant(tenant_id)) && !table_name.empty()) {
    const ObUserTableBuiltinSchemaEntry *entries = get_user_table_builtin_schema_entries();
    const int64_t cnt = get_user_table_builtin_schema_count();
    for (int64_t i = 0; !bret && i < cnt; ++i) {
      if (OB_NOT_NULL(entries[i].table_name_)
          && 0 == table_name.case_compare(entries[i].table_name_)) {
        bret = true;
      }
    }
  }
  return bret;
}

